<template>
  <Card>
    <CardHeader>
      <CardTitle>Throttling</CardTitle>
    </CardHeader>
    <CardContent>
      <NavigationGuard
        :saved-data="processedPassedData"
        :changed-data="processedDataFromForm"
        title="Warning"
        description="You have some unsaved changes on this tab! Save them before switching to another tab."
        confirm-text="Discard Changes"
      />
      <form id="settingsThrottlingForm" class="flex flex-col gap-6" @submit="onSubmit">
        <div class="flex items-center justify-between rounded-md border p-4">
          <div class="flex items-center gap-1">
            <label for="sms_no_delivery_demotion_enabled" class="text-sm font-medium">SMS No-Delivery Demotion</label>
            <Popover>
              <PopoverTrigger type="button"><CircleQuestionMarkIcon class="w-5 h-5" /></PopoverTrigger>
              <PopoverContent side="top" class="text-wrap max-w-72 w-fit p-4 z-40">
                <p class="font-semibold mb-4">SMS No-Delivery Demotion</p>
                {{ settingsFieldDescriptions.throttling.sms_no_delivery_demotion_enabled }}
              </PopoverContent>
            </Popover>
          </div>
          <Switch
            id="sms_no_delivery_demotion_enabled"
            :model-value="values.sms_no_delivery_demotion_enabled"
            @update:model-value="(v) => setFieldValue('sms_no_delivery_demotion_enabled', v)"
          />
        </div>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div class="flex flex-col gap-4">
            <FormItemWrapper
              label="General Exhaustion Threshold"
              name="general_exhaustion_threshold"
              :is-required="true"
              :description="settingsFieldDescriptions.throttling.general_exhaustion_threshold"
            >
              <template #default="{ slots }">
                <Input id="general_exhaustion_threshold" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="Project Exhaustion Threshold"
              name="project_exhaustion_threshold"
              :is-required="true"
              :description="settingsFieldDescriptions.throttling.project_exhaustion_threshold"
            >
              <template #default="{ slots }">
                <Input id="project_exhaustion_threshold" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="Exhausted Send Interval (days)"
              name="exhausted_send_interval_days"
              :is-required="true"
              :description="settingsFieldDescriptions.throttling.exhausted_send_interval_days"
            >
              <template #default="{ slots }">
                <Input id="exhausted_send_interval_days" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>
          </div>

          <div class="flex flex-col gap-4">
            <FormItemWrapper
              label="Global Daily Hard Cap"
              name="global_daily_hard_cap"
              :is-required="true"
              :description="settingsFieldDescriptions.throttling.global_daily_hard_cap"
            >
              <template #default="{ slots }">
                <Input id="global_daily_hard_cap" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="SMS Daily Hard Cap"
              name="sms_daily_hard_cap"
              :is-required="true"
              :description="settingsFieldDescriptions.throttling.sms_daily_hard_cap"
            >
              <template #default="{ slots }">
                <Input id="sms_daily_hard_cap" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="No-Delivery Streak Threshold"
              name="sms_no_delivery_streak_threshold"
              :is-required="true"
              :description="settingsFieldDescriptions.throttling.sms_no_delivery_streak_threshold"
            >
              <template #default="{ slots }">
                <Input id="sms_no_delivery_streak_threshold" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="No-Delivery Window (hours)"
              name="sms_no_delivery_window_hours"
              :is-required="true"
              :description="settingsFieldDescriptions.throttling.sms_no_delivery_window_hours"
            >
              <template #default="{ slots }">
                <Input id="sms_no_delivery_window_hours" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>
          </div>
        </div>

        <div class="flex justify-end">
          <Button
            type="submit"
            :loading="isUpdateSettingsThrottlingLoading"
            :disabled="isEqual(processedDataFromForm, processedPassedData) || isUpdateSettingsThrottlingLoading"
          >
            Save Throttling Settings
          </Button>
        </div>
      </form>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { isEqual } from 'lodash';
import { CircleQuestionMarkIcon } from 'lucide-vue-next';
import type { GetAllSystemSettingsResponse, ThrottlingConfig } from '~/client';
import { formSchema } from '~/constants/validationSchemas/recruitmentSettingsThrottling';
import { useUpdateSettingsThrottling } from '~/mutations/system/updateSettingsThrottling';
import { settingsFieldDescriptions } from '~/constants/recruitment/settingsFieldDescriptions';

const props = defineProps<{
  settings: GetAllSystemSettingsResponse;
}>();

definePageMeta({
  roles: ['admin'],
});

const { updateSettingsThrottling, isUpdateSettingsThrottlingLoading } = useUpdateSettingsThrottling();

const { handleSubmit, values, resetForm, setFieldValue } = useForm({
  validationSchema: formSchema,
  initialValues: {
    general_exhaustion_threshold: undefined,
    project_exhaustion_threshold: undefined,
    exhausted_send_interval_days: undefined,
    global_daily_hard_cap: undefined,
    sms_daily_hard_cap: undefined,
    sms_no_delivery_demotion_enabled: false,
    sms_no_delivery_streak_threshold: undefined,
    sms_no_delivery_window_hours: undefined,
  },
});

function hydrate(config: ThrottlingConfig) {
  resetForm({
    values: {
      general_exhaustion_threshold: config.general_exhaustion_threshold,
      project_exhaustion_threshold: config.project_exhaustion_threshold,
      exhausted_send_interval_days: config.exhausted_send_interval_days,
      global_daily_hard_cap: config.global_daily_hard_cap,
      sms_daily_hard_cap: config.sms_daily_hard_cap,
      sms_no_delivery_demotion_enabled: config.sms_no_delivery_demotion_enabled,
      sms_no_delivery_streak_threshold: config.sms_no_delivery_streak_threshold,
      sms_no_delivery_window_hours: config.sms_no_delivery_window_hours,
    },
  });
}

onMounted(() => hydrate(props.settings.throttling));

const processedPassedData = computed(() => props.settings.throttling);

const processedDataFromForm = computed<ThrottlingConfig>(() => ({
  general_exhaustion_threshold: toNumberOrNull(values.general_exhaustion_threshold) ?? 0,
  project_exhaustion_threshold: toNumberOrNull(values.project_exhaustion_threshold) ?? 0,
  exhausted_send_interval_days: toNumberOrNull(values.exhausted_send_interval_days) ?? 0,
  global_daily_hard_cap: toNumberOrNull(values.global_daily_hard_cap) ?? 0,
  sms_daily_hard_cap: toNumberOrNull(values.sms_daily_hard_cap) ?? 0,
  sms_no_delivery_demotion_enabled: values.sms_no_delivery_demotion_enabled ?? false,
  sms_no_delivery_streak_threshold: toNumberOrNull(values.sms_no_delivery_streak_threshold) ?? 0,
  sms_no_delivery_window_hours: toNumberOrNull(values.sms_no_delivery_window_hours) ?? 0,
}));

const onSubmit = handleSubmit(async (formValues) => {
  await updateSettingsThrottling(formValues);
  hydrate(formValues);
});
</script>
