import { updateThrottlingSettings, type ThrottlingConfig } from '~/client';

export const useUpdateSettingsThrottling = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: ThrottlingConfig): Promise<ThrottlingConfig> =>
      updateThrottlingSettings({
        composable: '$fetch',
        body: ref(data),
      }),
    onSuccess: () => {
      queryCache.invalidateQueries({ key: ['system-settings'] });
      showToastSuccess('Throttling settings updated successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    updateSettingsThrottling: mutateAsync,
    isUpdateSettingsThrottlingLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
